import React, { useState, useEffect } from 'react';

const SearchMatches = ({ 
    currentUser, 
    myMatches, 
    startChat, 
    handleExpressInterest, 
    viewUserProfile,
    initialSearchCriteria 
}) => {
    const [ageRange, setAgeRange] = useState(initialSearchCriteria?.ageRange || '');
    const [town, setTown] = useState(initialSearchCriteria?.town || '');
    const [results, setResults] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [hasSearched, setHasSearched] = useState(false);

    const performSearch = async () => {
        setLoading(true);
        setError(null);
        setHasSearched(true);
        try {
            const API_BASE = process.env.REACT_APP_API_URL ? `${process.env.REACT_APP_API_URL}/api/user` : `http://${window.location.hostname}:5000/api/user`;
            const phone = currentUser?.phone || currentUser?.phone_number || '0712345678';

            const response = await fetch(`${API_BASE}/match`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    phone: phone,
                    ageRange: ageRange,
                    town: town
                })
            });

            const data = await response.json();
            if (data.status === 'success' || data.success) {
                setResults(data.data?.matches || data.matches || []);
            } else {
                setError(data.message || 'Failed to fetch search results.');
                setResults([]);
            }
        } catch (err) {
            console.error('Search error:', err);
            setError('Network error occurred while searching.');
            setResults([]);
        } finally {
            setLoading(false);
        }
    };

    // Auto-search if criteria was provided initially
    useEffect(() => {
        if (initialSearchCriteria?.ageRange || initialSearchCriteria?.town) {
            performSearch();
        }
    }, []); // Run only on mount

    const isAcceptedMatch = (phone) => {
        return myMatches && myMatches.some(m => m.phone === phone || m.phone_number === phone);
    };

    const targetGender = currentUser?.gender?.toLowerCase() === 'male' ? 'Ladies' : 'Gentlemen';

    return (
        <div style={{ padding: '30px', maxWidth: '1400px', margin: '0 auto', width: '100%' }}>
            <h1 style={{ fontSize: '2.5rem', color: '#0f172a', marginBottom: '20px', fontWeight: '800' }}>
                ❤️ Search Matches
            </h1>

            {/* Search Bar */}
            <div style={{ backgroundColor: 'white', padding: '24px', borderRadius: '16px', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)', marginBottom: '40px', display: 'flex', gap: '15px', alignItems: 'flex-end', flexWrap: 'wrap' }}>
                <div style={{ flex: '1 1 200px' }}>
                    <label style={{ display: 'block', fontSize: '0.9rem', color: '#64748b', fontWeight: 'bold', marginBottom: '8px' }}>Age Range (e.g. 20-30)</label>
                    <input 
                        type="text" 
                        value={ageRange} 
                        onChange={e => setAgeRange(e.target.value)} 
                        placeholder="Age Range" 
                        style={{ width: '100%', padding: '12px 16px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '1rem' }}
                    />
                </div>
                <div style={{ flex: '2 1 300px' }}>
                    <label style={{ display: 'block', fontSize: '0.9rem', color: '#64748b', fontWeight: 'bold', marginBottom: '8px' }}>Town</label>
                    <input 
                        type="text" 
                        value={town} 
                        onChange={e => setTown(e.target.value)} 
                        placeholder="Enter town (e.g. Nairobi)" 
                        style={{ width: '100%', padding: '12px 16px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '1rem' }}
                    />
                </div>
                <button 
                    onClick={performSearch} 
                    disabled={loading}
                    style={{ padding: '12px 30px', backgroundColor: '#e11d48', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', fontSize: '1rem', cursor: loading ? 'not-allowed' : 'pointer', height: '45px', flex: '0 0 auto' }}
                >
                    {loading ? 'Searching...' : 'Search 🔍'}
                </button>
            </div>

            {/* Results Table */}
            <div style={{ backgroundColor: 'white', borderRadius: '16px', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)', overflow: 'hidden' }}>
                <div style={{ padding: '20px 24px', borderBottom: '1px solid #e5e7eb', backgroundColor: '#f8fafc', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '15px' }}>
                    <h2 style={{ margin: 0, fontSize: '1.25rem', color: '#0f172a', fontWeight: '700' }}>
                        Search Results
                    </h2>
                    <div style={{ fontSize: '0.9rem', color: '#64748b', fontWeight: '600', backgroundColor: '#f1f5f9', padding: '6px 16px', borderRadius: '20px' }}>
                        <span style={{color: '#0f172a'}}>{results.length} results</span> | Showing {targetGender}
                    </div>
                </div>

                {error && (
                    <div style={{ padding: '20px', backgroundColor: '#fef2f2', color: '#ef4444', textAlign: 'center', fontWeight: 'bold', borderBottom: '1px solid #fee2e2' }}>
                        ❌ {error}
                    </div>
                )}

                <div style={{ overflowX: 'auto', minHeight: '300px' }}>
                    {results.length === 0 ? (
                        <div style={{ padding: '80px 20px', textAlign: 'center' }}>
                            <div style={{ fontSize: '3rem', marginBottom: '15px' }}>{hasSearched ? '🔍' : '📝'}</div>
                            <p style={{ color: '#64748b', fontSize: '1.2rem', margin: 0, fontWeight: '600' }}>
                                {hasSearched ? 'No matches found for this criteria.' : 'Enter search criteria above to find matches.'}
                            </p>
                            {hasSearched && <p style={{ color: '#94a3b8', marginTop: '10px' }}>Try broadening your age range or clearing the town field.</p>}
                        </div>
                    ) : (
                        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.95rem' }}>
                            <thead style={{ position: 'sticky', top: 0, backgroundColor: '#f8fafc', zIndex: 1, boxShadow: '0 1px 2px rgba(0,0,0,0.05)' }}>
                                <tr>
                                    <th style={thStyle}>Photo</th>
                                    <th style={thStyle}>Name</th>
                                    <th style={thStyle}>Age</th>
                                    <th style={thStyle}>Town</th>
                                    <th style={thStyle}>Occupation</th>
                                    <th style={thStyle}>Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {results.map((user, idx) => (
                                    <tr key={user.phone_number || user.id || idx} style={{ borderBottom: '1px solid #f1f5f9', transition: 'background-color 0.2s' }} onMouseOver={(e) => e.currentTarget.style.backgroundColor = '#f8fafc'} onMouseOut={(e) => e.currentTarget.style.backgroundColor = 'transparent'}>
                                        <td style={tdStyle}>
                                            <div style={{ width: '50px', height: '50px', borderRadius: '50%', backgroundColor: '#e2e8f0', overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                                {user.profile_picture_url ? (
                                                    <img src={user.profile_picture_url} alt={user.name || user.full_name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                                ) : (
                                                    <span style={{ color: '#94a3b8', fontWeight: 'bold', fontSize: '1.2rem' }}>{(user.name || user.full_name)?.charAt(0)}</span>
                                                )}
                                            </div>
                                        </td>
                                        <td style={{ ...tdStyle, fontWeight: '700', color: '#1e293b', fontSize: '1.05rem' }}>{user.name || user.full_name}</td>
                                        <td style={{...tdStyle, color: '#64748b'}}>{user.age}</td>
                                        <td style={{...tdStyle, color: '#64748b'}}>{user.town || user.town_name || 'N/A'}</td>
                                        <td style={{...tdStyle, color: '#64748b'}}>{user.profession || 'N/A'}</td>
                                        <td style={tdStyle}>
                                            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                                                <button 
                                                    onClick={() => viewUserProfile && viewUserProfile(user)} 
                                                    style={btnStyle('#f1f5f9', '#475569')}
                                                >
                                                    👁️ View Profile
                                                </button>
                                                <button 
                                                    onClick={() => viewUserProfile && viewUserProfile(user)} 
                                                    style={btnStyle('#f8fafc', '#64748b', '1px solid #cbd5e1')}
                                                >
                                                    📄 Description
                                                </button>
                                                {isAcceptedMatch(user.phone || user.phone_number) ? (
                                                    <button 
                                                        onClick={() => startChat && startChat({...user, name: user.name || user.full_name, phone: user.phone || user.phone_number})} 
                                                        style={btnStyle('#ecfdf5', '#10b981')}
                                                    >
                                                        💬 Chat
                                                    </button>
                                                ) : (
                                                    <button 
                                                        onClick={() => handleExpressInterest && handleExpressInterest(user.phone || user.phone_number, user)} 
                                                        style={btnStyle('#fdf2f8', '#ec4899')}
                                                    >
                                                        ❤️ Express Interest
                                                    </button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    )}
                </div>
            </div>
        </div>
    );
};

// Styles
const thStyle = {
    padding: '16px 20px',
    color: '#64748b',
    fontWeight: '700',
    textTransform: 'uppercase',
    letterSpacing: '0.5px',
    fontSize: '0.75rem',
    borderBottom: '1px solid #e2e8f0'
};

const tdStyle = {
    padding: '20px',
    verticalAlign: 'middle',
    fontSize: '0.95rem'
};

const btnStyle = (bg, color, border = 'none') => ({
    padding: '8px 14px',
    backgroundColor: bg,
    color: color,
    border: border,
    borderRadius: '8px',
    fontWeight: '700',
    fontSize: '0.85rem',
    cursor: 'pointer',
    transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
});

export default SearchMatches;
